    uint32_t height;
    // Bytes from one row to the next; 0 = `width` times the pixel size.
    uint32_t stride;
    // An `ArcadePixelFormat` value.
    uint32_t format;
    // `ARCADE_FRAME_FLIP_Y`, or 0.
    uint32_t flags;
    // Must be 0.
